def _effective_prices(self, tenant: str) -> dict[str, int]:
    """Prices in effect for the tenant at query time.

    Declared prices override the built-in defaults per named metered type;
    a type the declaration leaves out keeps its default. Read at query
    time on the open transaction, so a later declaration never changes a
    bill already taken and never rewrites recorded usage.
    """
    declared = self._declared_prices(tenant)
    if not declared:
        return dict(USAGE_UNIT_PRICES)
    return {**USAGE_UNIT_PRICES, **declared}

def _usage_counts(
    self,
    tenant: str,
    since: datetime | None = None,
    until: datetime | None = None,
    types: tuple[str, ...] | None = None,
) -> dict[str, int]:
    """Cumulative per-type counts of the tenant's usage records.

    With no bounds every recorded record is counted, exactly as the
    cumulative baseline. ``since`` and ``until`` bound a closed interval on
    each record's own occurrence time (``created_at``): a record equal to
    either boundary counts. A window with ``since`` later than ``until``
    contains no records, so every type is omitted. ``types`` keeps only
    records whose metered type is in the set and combines with the window
    as an intersection; when it is ``None`` every type is counted.
    """
    if since is None and until is None:
        rows = self.store.connection.execute(
            "SELECT type, COUNT(*) AS count FROM usage_records WHERE tenant = ? GROUP BY type",
            (tenant,),
        ).fetchall()
        counts = {row["type"]: row["count"] for row in rows}
    else:
        rows = self.store.connection.execute(
            "SELECT type, created_at FROM usage_records WHERE tenant = ?",
            (tenant,),
        ).fetchall()
        counts = {}
        for row in rows:
            if not self._within_window(_parse_stored_time(row["created_at"]), since, until):
                continue
            counts[row["type"]] = counts.get(row["type"], 0) + 1
    return {
        usage_type: counts[usage_type]
        for usage_type in USAGE_TYPES
        if counts.get(usage_type) and (types is None or usage_type in types)
    }

